/**
 * Python-flavoured exception types.
 *
 * Each error carries the exception class name Python would show on the last
 * line of a traceback, so the traceback renderer can stay generic.
 */

export class PyError extends Error {
  constructor(message, pyType) {
    super(message);
    this.name = pyType;
    this.pyType = pyType;
  }
}

export class PyValueError extends PyError {
  constructor(message) {
    super(message, 'ValueError');
  }
}

export class PyTypeError extends PyError {
  constructor(message) {
    super(message, 'TypeError');
  }
}

