/**
 * Python `int(str)` semantics (base 10).
 *
 * Differences from Number.parseInt / Number() that matter here:
 *   - surrounding whitespace is stripped, but interior whitespace is invalid
 *   - a single leading '+' or '-' is allowed
 *   - underscores may separate digits ("1_0" -> 10) but not lead, trail or double
 *   - leading zeros are fine ("07" -> 7)
 *   - any Unicode decimal digit is accepted ("١٢", "１２")
 *   - floats, hex prefixes and empty strings are rejected
 */

import { PyValueError } from './errors.mjs';

const UNICODE_DIGIT = /\p{Nd}/u;
// Python's str.strip() removes Unicode whitespace; \s plus the few code points
// JS omits covers every character str.strip() considers blank.
const PY_WHITESPACE = /^[\s-]+|[\s-]+$/gu;

function isUnicodeDigit(codePoint) {
  return UNICODE_DIGIT.test(String.fromCodePoint(codePoint));
}

/**
 * Numeric value of a Unicode decimal digit. Nd digits always appear as runs of
 * ten consecutive code points starting at the digit zero, so walking backwards
 * to the first non-digit code point yields the value directly.
 */
function digitValue(codePoint) {
  for (let offset = 0; offset < 10; offset += 1) {
    const candidate = codePoint - offset;
    if (!isUnicodeDigit(candidate)) return -1;
    if (candidate === 0 || !isUnicodeDigit(candidate - 1)) return offset;
  }
  return -1;
}

export function pyStrip(text) {
  return text.replace(PY_WHITESPACE, '');
}

/** Parses `text` like Python's int(); throws PyValueError when malformed. */
export function pyInt(text) {
  const body = pyStrip(String(text));
  let index = 0;
  let sign = 1;

  if (body[index] === '+' || body[index] === '-') {
    if (body[index] === '-') sign = -1;
    index += 1;
  }

  const digits = [...body.slice(index)];
  if (digits.length === 0) throw new PyValueError(invalidLiteral(text));

  let value = 0;
  let previousWasUnderscore = true; // forbids a leading underscore
  for (const char of digits) {
    if (char === '_') {
      if (previousWasUnderscore) throw new PyValueError(invalidLiteral(text));
      previousWasUnderscore = true;
      continue;
    }
    const digit = digitValue(char.codePointAt(0));
    if (digit < 0) throw new PyValueError(invalidLiteral(text));
    value = value * 10 + digit;
    previousWasUnderscore = false;
  }
  if (previousWasUnderscore) throw new PyValueError(invalidLiteral(text));

  return sign * value;
}

function invalidLiteral(text) {
  return `invalid literal for int() with base 10: '${text}'`;
}

/** True when `value` is an integer Python would accept as an index/byte. */
export function isPyInteger(value) {
  return typeof value === 'number' && Number.isInteger(value);
}

