/**
 * Python `bytes` stand-in.
 *
 * Backed by an ordinary array of integers so the whole pipeline stays in plain
 * JavaScript values: an immutable sequence of ints in range(0, 256).
 */

import { PyValueError, PyTypeError } from './errors.mjs';
import { isPyInteger } from './ints.mjs';

export class PyBytes {
  #octets;

  constructor(octets) {
    this.#octets = Object.freeze([...octets]);
  }

  get length() {
    return this.#octets.length;
  }

  /** Byte at `index`, or undefined when out of range. */
  at(index) {
    return this.#octets[index];
  }

  /** Half-open slice [start, stop) as a new PyBytes. */
  slice(start, stop) {
    return new PyBytes(this.#octets.slice(start, stop));
  }

  toArray() {
    return [...this.#octets];
  }

  *[Symbol.iterator]() {
    yield* this.#octets;
  }

  /** Python's repr(bytes): b'...' with non-printables escaped. */
  toString() {
    let out = "b'";
    for (const byte of this.#octets) {
      if (byte === 0x27) out += "\\'";
      else if (byte === 0x5c) out += '\\\\';
      else if (byte === 0x0a) out += '\\n';
      else if (byte === 0x0d) out += '\\r';
      else if (byte === 0x09) out += '\\t';
      else if (byte >= 0x20 && byte <= 0x7e) out += String.fromCharCode(byte);
      else out += `\\x${byte.toString(16).padStart(2, '0')}`;
    }
    return `${out}'`;
  }
}

/**
 * Python's bytes(iterable_of_ints).
 *
 * Rejects non-integers and out-of-range values with the exact messages
 * CPython raises, since those surface in the program's traceback.
 */
export function bytesFromInts(values) {
  const octets = [];
  for (const value of values) {
    if (!isPyInteger(value)) {
      throw new PyTypeError("'float' object cannot be interpreted as an integer");
    }
    if (value < 0 || value > 255) {
      throw new PyValueError('bytes must be in range(0, 256)');
    }
    octets.push(value);
  }
  return new PyBytes(octets);
}

