/**
 * Rendering of uncaught exceptions the way the frozen (PyInstaller) build of
 * the original script reports them: a traceback on stderr, then the PyInstaller
 * banner, then exit status 1.
 */

import { PyError } from './errors.mjs';

/**
 * @param {Error} error         the exception that escaped main()
 * @param {object} options
 * @param {string} options.scriptName   e.g. "test4"
 * @param {Array<{line: number, name: string}>} options.frames
 *        call stack, outermost first, as Python would list it
 */
export function formatTraceback(error, { scriptName, frames }) {
  const lines = ['Traceback (most recent call last):'];
  for (const frame of frames) {
    lines.push(`  File "${scriptName}.py", line ${frame.line}, in ${frame.name}`);
  }
  const pyType = error instanceof PyError ? error.pyType : 'RuntimeError';
  lines.push(`${pyType}: ${error.message}`);
  return lines.join('\n');
}

export function pyInstallerBanner(scriptName, pid) {
  return `[PYI-${pid}:ERROR] Failed to execute script '${scriptName}' due to unhandled exception!`;
}

