/**
 * Python's print() / str() over the values this program produces.
 *
 * Writes are unbuffered single-shot writes to the raw stdout/stderr streams so
 * that ordering between the two matches CPython's.
 */

export function pyStr(value) {
  if (value === null || value === undefined) return 'None';
  if (typeof value === 'boolean') return value ? 'True' : 'False';
  return String(value);
}

export function printOut(...values) {
  process.stdout.write(`${values.map(pyStr).join(' ')}\n`);
}

export function printErr(...values) {
  process.stderr.write(`${values.map(pyStr).join(' ')}\n`);
}

