/** Control-flow and validation errors used by the argparse port. */

/** Raised instead of calling process.exit(), so the entry point owns exiting. */
export class SystemExit extends Error {
  constructor(code, { stdout = '', stderr = '' } = {}) {
    super(`SystemExit: ${code}`);
    this.name = 'SystemExit';
    this.code = code;
    this.stdout = stdout;
    this.stderr = stderr;
  }
}

/** A `type=` callable rejecting its input, e.g. int('abc'). */
export class ArgumentTypeError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ArgumentTypeError';
  }
}

