/**
 * A seekable byte stream over a PyBytes / integer array, standing in for the
 * io.BytesIO object construct parses from.
 *
 * Reading fewer bytes than requested is an error here, exactly as construct
 * treats a truncated stream.
 */

import { StreamError } from './errors.mjs';

export class ByteStream {
  #octets;
  #position;

  constructor(source) {
    this.#octets = typeof source?.toArray === 'function' ? source.toArray() : [...source];
    this.#position = 0;
  }

  get position() {
    return this.#position;
  }

  get length() {
    return this.#octets.length;
  }

  /** Reads exactly `count` bytes; throws StreamError when the stream is short. */
  read(count, path) {
    if (count < 0) {
      throw new StreamError(`could not read ${count} bytes, negative amount`, path);
    }
    const chunk = this.#octets.slice(this.#position, this.#position + count);
    if (chunk.length !== count) {
      throw new StreamError(
        `could not read enough bytes, expected ${count}, found ${chunk.length}`,
        path,
      );
    }
    this.#position += count;
    return chunk;
  }

  /** Remaining bytes, without consuming them. */
  peekRest() {
    return this.#octets.slice(this.#position);
  }

  seek(offset) {
    this.#position = offset;
    return this.#position;
  }
}

