/**
 * @param {*} value        value to render
 * @param {string} indentation  newline + current indent, e.g. "\n    "
 */
export function stringify(value, indentation = `\n${STEP}`) {
  if (value === null || value === undefined) return 'None';
  if (typeof value === 'boolean') return value ? 'True' : 'False';
  if (typeof value === 'number' || typeof value === 'bigint') return `${value}`;
  if (typeof value === 'string') return stringifyString(value);
  if (value instanceof PyBytes) return stringifyBytes(value);

  const nested = indentation + STEP;
  if (Array.isArray(value)) {
    if (value.length === 0) return 'ListContainer: ';
    const items = value.map((item) => `${indentation}${stringify(item, nested)}`);
    return ['', 'ListContainer: ', ...items].join('');
  }
  if (typeof value.visibleEntries === 'function') {
    const entries = [...value.visibleEntries()];
    if (entries.length === 0) return 'Container: ';
    const fields = entries.map(
      ([key, item]) => `${indentation}${key} = ${stringify(item, nested)}`,
    );
    return ['', 'Container: ', ...fields].join('');
  }
  if (value instanceof Map) {
    const fields = [...value.entries()]
      .filter(([key]) => !isHidden(String(key)))
      .map(([key, item]) => `${indentation}${key} = ${stringify(item, nested)}`);
    return ['', 'Container: ', ...fields].join('');
  }
  return String(value);
}

