/**
 * Base class for construct subconstructs.
 *
 * Python spells field naming as `"field1" / Int8ul`, which relies on operator
 * overloading. JavaScript has no `/` overload, so the same wiring is exposed as
 * `Int8ul.named("field1")` (or the `named()` helper re-exported from index).
 */

import { ByteStream } from './stream.mjs';
import { SizeofError } from './errors.mjs';

export class Subcon {
  constructor({ name = null } = {}) {
    this.name = name;
  }

  /** Returns a copy of this subcon bound to a field name. */
  named(name) {
    const clone = Object.create(Object.getPrototypeOf(this));
    Object.assign(clone, this);
    clone.name = name;
    return clone;
  }

  /** Subclass hook: parse from an open stream. */
  _parse(_stream, _context, _path) {
    throw new SizeofError(`${this.constructor.name} does not implement _parse`);
  }

  /** Subclass hook: byte length, when fixed. */
  _sizeof(_context, path) {
    throw new SizeofError('cannot calculate size', path);
  }

  parseStream(stream, context = null, path = 'parsing') {
    return this._parse(stream, context, path);
  }

  /** construct's `parse(data)`: parse a bytes object from its start. */
  parse(data) {
    return this.parseStream(new ByteStream(data), null, 'parsing');
  }

  sizeof(context = null) {
    return this._sizeof(context, 'sizeof');
  }
}

/** `named("field1", Int8ul)` — the readable stand-in for `"field1" / Int8ul`. */
export function named(name, subcon) {
  return subcon.named(name);
}

