/**
 * Fixed-width integer subcons (construct's Int8ul, Int16ub, ... family).
 *
 * Decoding is plain integer arithmetic over the byte list: bytes are combined
 * most-significant-first with multiply/add, then re-centred for signed formats.
 * 64-bit widths use BigInt so no precision is lost.
 */

import { Subcon } from './subcon.mjs';
import { FormatFieldError } from './errors.mjs';

class IntegerField extends Subcon {
  constructor({ width, signed, little, label }) {
    super();
    this.width = width;
    this.signed = signed;
    this.little = little;
    this.label = label;
  }

  _parse(stream, _context, path) {
    const chunk = stream.read(this.width, path);
    const ordered = this.little ? [...chunk].reverse() : chunk;
    return this.width >= 8 ? decodeBig(ordered, this.signed) : decodeSmall(ordered, this.signed);
  }

  _sizeof() {
    return this.width;
  }

  /** Range check used when this field is built rather than parsed. */
  validate(value, path) {
    const span = 2 ** (8 * this.width);
    const low = this.signed ? -span / 2 : 0;
    const high = this.signed ? span / 2 - 1 : span - 1;
    if (Number(value) < low || Number(value) > high) {
      throw new FormatFieldError(
        `value ${value} out of range for ${this.label} (${low}..${high})`,
        path,
      );
    }
    return value;
  }

  toString() {
    return this.label;
  }
}

function decodeSmall(bytesBigEndianFirst, signed) {
  let value = 0;
  for (const byte of bytesBigEndianFirst) value = value * 256 + byte;
  if (!signed) return value;
  const span = 2 ** (8 * bytesBigEndianFirst.length);
  return value >= span / 2 ? value - span : value;
}

function decodeBig(bytesBigEndianFirst, signed) {
  let value = 0n;
  for (const byte of bytesBigEndianFirst) value = value * 256n + BigInt(byte);
  if (!signed) return value;
  const span = 2n ** BigInt(8 * bytesBigEndianFirst.length);
  return value >= span / 2n ? value - span : value;
}

function makeInt(width, signed, little) {
  const label = `Int${width * 8}${signed ? 's' : 'u'}${little ? 'l' : 'b'}`;
  return new IntegerField({ width, signed, little, label });
}

export const Int8ub = makeInt(1, false, false);
export const Int8ul = makeInt(1, false, true);
export const Int8sb = makeInt(1, true, false);
export const Int8sl = makeInt(1, true, true);

export const Int16ub = makeInt(2, false, false);
export const Int16ul = makeInt(2, false, true);
export const Int16sb = makeInt(2, true, false);
export const Int16sl = makeInt(2, true, true);

