export const Int24ul = makeInt(3, false, true);
export const Int24sb = makeInt(3, true, false);
export const Int24sl = makeInt(3, true, true);

export const Int32ub = makeInt(4, false, false);
export const Int32ul = makeInt(4, false, true);
export const Int32sb = makeInt(4, true, false);
export const Int32sl = makeInt(4, true, true);

export const Int64ub = makeInt(8, false, false);
export const Int64ul = makeInt(8, false, true);
export const Int64sb = makeInt(8, true, false);
export const Int64sl = makeInt(8, true, true);

// construct's convenience aliases (big-endian, unsigned).
export const Byte = Int8ub;
export const Short = Int16ub;
