/**
 * construct's Struct: parses its named subcons in order into a Container.
 *
 * Like construct, the result carries the bookkeeping keys `_io` (the stream)
 * and `_` (the parent context), both hidden from the text form, and each
 * subcon sees the partially-built container as its context.
 */

import { Subcon } from './subcon.mjs';
import { Container } from './container.mjs';
import { ByteStream } from './stream.mjs';
import { SizeofError } from './errors.mjs';

export class Struct extends Subcon {
  constructor(...subcons) {
    super();
    this.subcons = subcons;
  }

  _parse(stream, context, path) {
    const result = new Container();
    result.set('_io', stream);
    if (context !== null && context !== undefined) result.set('_', context);

    for (const subcon of this.subcons) {
      const subPath = subcon.name ? `${path} -> ${subcon.name}` : path;
      const value = subcon._parse(stream, result, subPath);
      if (subcon.name) result.set(subcon.name, value);
    }
    return result;
  }

  _sizeof(context, path) {
    let total = 0;
    for (const subcon of this.subcons) {
      const size = subcon._sizeof(context, path);
      if (!Number.isInteger(size)) {
        throw new SizeofError('cannot calculate size of variable-length member', path);
      }
      total += size;
    }
    return total;
  }

  parse(data) {
    return this._parse(new ByteStream(data), null, 'parsing');
  }
}

/** Factory mirroring `construct.Struct(...)` being callable without `new`. */
export function makeStruct(...subcons) {
  return new Struct(...subcons);
}

