#!/usr/bin/env node
/**
 * Node port of /workspace/dataset/construct/test4.py
 *
 *   parse two required int options, pack them into a two-byte buffer, and
 *   print the construct Container produced by parsing it as two Int8ul fields.
 */

import { ArgumentParser, SystemExit } from './lib/argparse/index.mjs';
import { pyInt } from './lib/pycompat/ints.mjs';
import { bytesFromInts } from './lib/pycompat/bytes.mjs';
import { printOut } from './lib/pycompat/print.mjs';
import { formatTraceback, pyInstallerBanner } from './lib/pycompat/traceback.mjs';
import construct, { named } from './lib/construct/index.mjs';

// argparse names the converter in its error messages ("invalid int value: ...").
pyInt.pyName = 'int';

// Matches the frozen binary's prog name, which argparse takes from argv[0].
const PROG = 'test4_executable';
const SCRIPT = 'test4';

function main(argv) {
  const parser = new ArgumentParser({ prog: PROG });
  parser.addArgument(['--a'], { type: pyInt, required: true });
  parser.addArgument(['--b'], { type: pyInt, required: true });
  const args = parser.parseArgs(argv);

  const structFormat = construct.Struct(
    named('field1', construct.Int8ul), // 定义第一个字段
    named('field2', construct.Int8ul), // 定义第二个字段
  );
  const data = bytesFromInts([args.a, args.b]);
  const result = structFormat.parse(data); // 解析结构体
  printOut(result);
}

try {
  main(process.argv.slice(2));
} catch (error) {
  if (error instanceof SystemExit) {
    if (error.stdout) process.stdout.write(error.stdout);
    if (error.stderr) process.stderr.write(error.stderr);
    process.exit(error.code);
  }
  // Uncaught exception: same traceback shape and exit status as the original.
  process.stderr.write(
    `${formatTraceback(error, {
      scriptName: SCRIPT,
      frames: [
        { line: 20, name: '<module>' },
        { line: 15, name: 'main' },
      ],
    })}\n`,
  );
  process.stderr.write(`${pyInstallerBanner(SCRIPT, process.pid)}\n`);
  process.exit(1);
}

