const MAX_HELP_POSITION = 24;
const INDENT = 2;

/**
 * argparse sizes its output from the terminal, then reserves two columns:
 * HelpFormatter uses shutil.get_terminal_size().columns - 2, and
 * get_terminal_size() honours $COLUMNS before falling back to 80.
 */
