/**
 * Minimal port of argparse.ArgumentParser covering what the original script
 * uses: `--name value` optionals with `type=` conversion and `required=True`,
 * plus the automatic `-h/--help`.
 *
 * Reproduced behaviours that the reference binary exposes:
 *   - `--a 5`, `--a=5` and unambiguous prefixes of a long option
 *   - a value that looks like a negative number is accepted (`--a -1`),
 *     because no declared option looks like a negative number
 *   - missing required options are reported *before* unrecognized arguments
 *   - errors print usage + "prog: error: ..." on stderr and exit with status 2
 */

import { SystemExit, ArgumentTypeError } from './errors.mjs';
import { formatHelp, formatUsage } from './formatter.mjs';

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

export class ArgumentParser {
  constructor({ prog } = {}) {
    this.prog = prog ?? 'prog';
    this.actions = [];
    this.addArgument(['-h', '--help'], {
      nargs: 0,
      action: 'help',
      help: 'show this help message and exit',
    });
  }

  /**
   * @param {string[]} flags   option strings, e.g. ['--a']
   * @param {object} options   {type, required, help, nargs, action, metavar}
   */
  addArgument(flags, { type, required = false, help = '', nargs = 1, action = 'store', metavar } = {}) {
    const dest = flags
      .find((flag) => flag.startsWith('--'))
      ?.slice(2)
      .replace(/-/g, '_') ?? flags[0].slice(1);
    this.actions.push({
      optionStrings: [...flags],
      dest,
      type,
      required,
      help,
      nargs,
      action,
      metavar: metavar ?? dest.toUpperCase(),
    });
    return this;
  }

  formatUsage() {
    return `${formatUsage(this.prog, this.actions)}\n`;
  }

  formatHelp() {
    return formatHelp(this.prog, this.actions);
  }

  /** Exits with status 2 after printing usage and the message, like argparse. */
  error(message) {
    throw new SystemExit(2, {
      stderr: `${this.formatUsage()}${this.prog}: error: ${message}\n`,
    });
  }

  /** Resolves `token` to a declared option, allowing unambiguous prefixes. */
  #lookupOption(token) {
    const exact = this.actions.find((action) => action.optionStrings.includes(token));
    if (exact) return exact;
    if (!token.startsWith('--')) return null;
    const matches = this.actions.filter((action) =>
      action.optionStrings.some((flag) => flag.startsWith('--') && flag.startsWith(token)),
    );
    if (matches.length === 1) return matches[0];
    if (matches.length > 1) {
      const flags = matches.flatMap((action) =>
        action.optionStrings.filter((flag) => flag.startsWith(token)),
      );
      this.error(`ambiguous option: ${token} could match ${flags.join(', ')}`);
    }
    return null;
  }

  /** True when `token` starts an option rather than being a value. */
  #looksLikeOption(token) {
    if (!token.startsWith('-') || token === '-' || token === '--') return false;
    return !NEGATIVE_NUMBER.test(token);
  }

  #convert(action, raw) {
    if (!action.type) return raw;
    try {
      return action.type(raw);
    } catch (error) {
      if (error instanceof ArgumentTypeError) {
        this.error(`argument ${action.optionStrings.join('/')}: ${error.message}`);
      }
      const typeName = action.type.pyName ?? action.type.name ?? 'value';
      this.error(
        `argument ${action.optionStrings.join('/')}: invalid ${typeName} value: '${raw}'`,
      );
      return undefined; // unreachable: error() throws
    }
  }

  /**
   * @param {string[]} argv  arguments after the program name
   * @returns {object}       namespace of dest -> converted value
   */
  parseArgs(argv) {
    const namespace = {};
    const seen = new Set();
    const extras = [];

    for (let index = 0; index < argv.length; index += 1) {
      const token = argv[index];

      if (!this.#looksLikeOption(token)) {
        extras.push(token);
        continue;
      }

      const [head, ...rest] = splitExplicitValue(token);
      const action = this.#lookupOption(head);
      if (!action) {
        extras.push(token);
        continue;
      }

      if (action.action === 'help') {
        throw new SystemExit(0, { stdout: this.formatHelp() });
      }

      let raw;
      if (rest.length > 0) {
        [raw] = rest;
      } else {
        const next = argv[index + 1];
        if (next === undefined || this.#looksLikeOption(next)) {
          this.error(`argument ${action.optionStrings.join('/')}: expected one argument`);
        }
        raw = next;
        index += 1;
      }

      namespace[action.dest] = this.#convert(action, raw);
      seen.add(action.dest);
    }

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action.dest))
      .map((action) => action.optionStrings.join('/'));
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return namespace;
  }
}

/** Splits `--a=5` into ['--a', '5']; leaves other tokens as a single element. */
function splitExplicitValue(token) {
  const separator = token.indexOf('=');
  if (!token.startsWith('--') || separator === -1) return [token];
  return [token.slice(0, separator), token.slice(separator + 1)];
}

